"""Micro-benchmark of candidate file_info return-type shims.
All must remain unpackable as a 4-tuple (json_path, json_exists, ddb_path, ddb_exists).
"""

import os
import statistics
import time
import typing

STORAGE = "/tmp/audit6/binfo"
os.makedirs(STORAGE, exist_ok=True)
with open(f"{STORAGE}/users.json", "w") as f:
    f.write('{"a": 1}')


# ---------- variant 0: upstream (plain tuple literal) ----------
def fi_upstream(db_name):
    base = f"{STORAGE}/{db_name}"
    j, d = f"{base}.json", f"{base}.ddb"
    return j, os.path.exists(j), d, os.path.exists(d)


# ---------- variant 1: plain tuple subclass, lazy props ----------
class FileInfo1(tuple):
    __slots__ = ()

    @property
    def json_path(self):
        return self[0]

    @property
    def json_exists(self):
        return self[1]

    @property
    def ddb_path(self):
        return self[2]

    @property
    def ddb_exists(self):
        return self[3]

    @property
    def is_file(self):
        return self[1] or self[3]

    @property
    def _p(self):
        return self[0] if self[1] else (self[2] if self[3] else None)

    @property
    def size_bytes(self):
        p = self._p
        return os.path.getsize(p) if p else 0

    @property
    def modified_time(self):
        p = self._p
        return os.path.getmtime(p) if p else None


def fi_v1(db_name):
    base = f"{STORAGE}/{db_name}"
    j, d = f"{base}.json", f"{base}.ddb"
    return FileInfo1((j, os.path.exists(j), d, os.path.exists(d)))


# ---------- variant 2: typing.NamedTuple + extra properties ----------
class FileInfo2(typing.NamedTuple):
    json_path: str
    json_exists: bool
    ddb_path: str
    ddb_exists: bool

    @property
    def is_file(self):
        return self.json_exists or self.ddb_exists

    @property
    def size_bytes(self):
        p = self.json_path if self.json_exists else (self.ddb_path if self.ddb_exists else None)
        return os.path.getsize(p) if p else 0

    @property
    def modified_time(self):
        p = self.json_path if self.json_exists else (self.ddb_path if self.ddb_exists else None)
        return os.path.getmtime(p) if p else None


def fi_v2(db_name):
    base = f"{STORAGE}/{db_name}"
    j, d = f"{base}.json", f"{base}.ddb"
    return FileInfo2(j, os.path.exists(j), d, os.path.exists(d))


# ---------- variant 3: tuple subclass built via tuple.__new__ (fastest ctor) ----------
class FileInfo3(tuple):
    __slots__ = ()

    json_path = property(lambda s: s[0])
    json_exists = property(lambda s: s[1])
    ddb_path = property(lambda s: s[2])
    ddb_exists = property(lambda s: s[3])
    is_file = property(lambda s: s[1] or s[3])
    size_bytes = property(lambda s: os.path.getsize(s[0] if s[1] else s[2]) if (s[1] or s[3]) else 0)
    modified_time = property(lambda s: os.path.getmtime(s[0] if s[1] else s[2]) if (s[1] or s[3]) else None)


def fi_v3(db_name):
    base = f"{STORAGE}/{db_name}"
    j, d = f"{base}.json", f"{base}.ddb"
    return tuple.__new__(FileInfo3, (j, os.path.exists(j), d, os.path.exists(d)))


def timeit(fn, n=200_000):
    for _ in range(n // 20):
        fn()
    reps = []
    for _ in range(5):
        t0 = time.perf_counter()
        for _ in range(n):
            fn()
        reps.append(n / (time.perf_counter() - t0))
    return max(reps), statistics.median(reps)


variants = [
    ("upstream tuple literal", fi_upstream),
    ("v1 tuple subclass", fi_v1),
    ("v2 typing.NamedTuple", fi_v2),
    ("v3 tuple.__new__ subcls", fi_v3),
]

print(f"{'variant':28s} {'best call/s':>14s} {'median call/s':>14s} {'vs upstream':>12s}")
base_best = None
for name, fn in variants:
    # correctness: must unpack
    a, b, c, d = fn("users")
    assert a.endswith("users.json") and b is True and c.endswith("users.ddb") and d is False, name
    best, med = timeit(fn)
    if base_best is None:
        base_best = best
    print(f"{name:28s} {best:14,.0f} {med:14,.0f} {best / base_best * 100:11.1f}%")

# also verify extras work
for name, cls_fn in [("v1", fi_v1), ("v2", fi_v2), ("v3", fi_v3)]:
    r = cls_fn("users")
    print(f"{name}: size_bytes={r.size_bytes} is_file={r.is_file} mtime={r.modified_time is not None} json_path_attr={r.json_path.endswith('users.json')}")

